<script setup lang="ts">import{computed,ref,watch}from"vue";import{pb}from"@/infrastructure/pocketbase/client";import{loanHistoryRepository}from"@/domain/library/repository";import{buildCopyDetailsSummary,copyDisplayCode}from"@/domain/library/copyDetails";import type{LibraryCopyRecord,LoanHistoryRecord}from"@/domain/library/records";import LibraryLoanDialog from"./LibraryLoanDialog.vue";const props=defineProps<{copy:LibraryCopyRecord|null}>();const emit=defineEmits<{close:[];edit:[LibraryCopyRecord];changed:[LibraryCopyRecord]}>();const history=ref<LoanHistoryRecord[]>([]),loading=ref(false),error=ref(""),loanOpen=ref(false);const summary=computed(()=>props.copy?buildCopyDetailsSummary(props.copy,history.value):null);const title=computed(()=>props.copy?.expand?.titulo);const poster=computed(()=>title.value?.poster?pb.files.getURL(title.value,title.value.poster,{thumb:"360x540"}):title.value?.poster_url||"");const stateLabel=(s:string)=>({Emprestado:"Emprestado",Atrasado:"Devolução em atraso",Devolvido:"Devolvido",Perdido:"Marcado como perdido",Danificado:"Devolvido com danos",Cancelado:"Empréstimo cancelado"}[s]||s);async function load(copy:LibraryCopyRecord){loading.value=true;error.value="";try{history.value=(await loanHistoryRepository.list({page:1,perPage:200,filter:`exemplar = "${copy.id}"`,sort:"-data_emprestimo",expand:"pessoa,titulo"})).items}catch(c){error.value=c instanceof Error?c.message:String(c)}finally{loading.value=false}}watch(()=>props.copy,copy=>{history.value=[];if(copy)void load(copy)},{immediate:true});function formatDate(value?:string){return value?new Intl.DateTimeFormat("pt-PT",{dateStyle:"medium"}).format(new Date(value)):"—"}async function loanSaved(copy:LibraryCopyRecord){loanOpen.value=false;emit("changed",copy);await load(copy)}</script><template><Teleport to="body"><div v-if="copy" class="dialog-backdrop" @click.self="emit('close')"><section class="dialog-panel library-copy-detail" role="dialog" aria-modal="true" aria-labelledby="copy-detail-title"><div class="dialog-header"><div><p class="eyebrow">{{copyDisplayCode(copy)}}</p><h2 id="copy-detail-title">{{title?.titulo||'Exemplar sem título'}}</h2></div><button class="icon-button" type="button" aria-label="Fechar detalhe" @click="emit('close')">×</button></div><div v-if="error" class="form-alert form-alert-error" role="alert">{{error}}</div><div class="library-detail-layout"><div class="library-detail-poster"><img v-if="poster" :src="poster" :alt="`Capa de ${title?.titulo||'título'}`"/><span v-else aria-hidden="true">▤</span></div><div><div class="library-detail-actions"><button class="button button-secondary" type="button" @click="emit('edit',copy)">Editar exemplar</button><button class="button button-primary" type="button" @click="loanOpen=true">{{copy.emprestado?'Gerir empréstimo':'Emprestar'}}</button></div><dl class="library-detail-facts"><div><dt>Formato</dt><dd>{{copy.expand?.formato?.nome||'—'}}</dd></div><div><dt>Edição</dt><dd>{{copy.expand?.tipo_edicao?.nome||'—'}}</dd></div><div><dt>Estado físico</dt><dd>{{copy.estado_fisico||'—'}}</dd></div><div><dt>Região</dt><dd>{{copy.regiao||'—'}}</dd></div><div><dt>Localização</dt><dd>{{copy.localizacao||'—'}}</dd></div><div><dt>Número da cópia</dt><dd>{{copy.numero_copia||1}}</dd></div><div><dt>Código interno</dt><dd>{{copy.codigo_interno||'—'}}</dd></div><div><dt>Código de barras</dt><dd>{{copy.codigo_barras||'—'}}</dd></div><div><dt>Selado</dt><dd>{{copy.selado?'Sim':'Não'}}</dd></div><div><dt>Steelbook</dt><dd>{{copy.steelbook?'Sim':'Não'}}</dd></div><div><dt>Criado</dt><dd>{{formatDate(copy.created)}}</dd></div><div><dt>Atualizado</dt><dd>{{formatDate(copy.updated)}}</dd></div></dl></div></div><section class="detail-section"><h3>Resumo de empréstimos</h3><p v-if="summary"><strong>{{summary.totalLoans}}</strong> empréstimos · <strong>{{summary.totalRenewals}}</strong> renovações <span v-if="summary.overdue">· devolução em atraso</span></p><p v-if="copy.notas" class="detail-copy">{{copy.notas}}</p></section><section class="detail-section" aria-labelledby="copy-history-title"><h3 id="copy-history-title">Histórico deste exemplar</h3><p v-if="loading" aria-live="polite">A carregar histórico…</p><p v-else-if="!history.length">Este exemplar ainda não tem empréstimos registados.</p><ol v-else class="copy-history-list"><li v-for="item in history" :key="item.id"><strong>{{stateLabel(item.estado)}}</strong><span>{{item.expand?.pessoa?.nome||item.pessoa}}</span><span>{{formatDate(item.data_emprestimo)}} → {{formatDate(item.data_devolucao||item.data_prevista)}}</span><small>{{item.renovacoes||0}} renovações</small><p v-if="item.notas">{{item.notas}}</p></li></ol></section><LibraryLoanDialog :open="loanOpen" :copy="copy" @close="loanOpen=false" @saved="loanSaved"/></section></div></Teleport></template>
